<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';
use Kios\Infrastructure\{Database,StaffAccountService};use Kios\MerchantOperations\{StaffSessionIdentity,BillDrafts};
$db=Database::connect();$meta=json_decode(file_get_contents($argv[1]),true);$secrets=json_decode(file_get_contents($argv[2]),true);$a=$meta['merchants']['a'];$b=$meta['merchants']['b'];$r=['passed'=>0,'failed'=>0,'cases'=>[]];
function ok(bool $v):void{if(!$v)throw new RuntimeException('Assertion failed');}function deny(callable $f):void{try{$f();}catch(DomainException|InvalidArgumentException|PDOException){return;}throw new RuntimeException('Expected denial');}function test(string $n,callable $f):void{global$r;try{$f();$r['passed']++;$r['cases'][$n]='PASS';}catch(Throwable $e){$r['failed']++;$r['cases'][$n]=get_class($e).':'.$e->getMessage().' at '.basename($e->getFile()).':'.$e->getLine();}}function req():string{return bin2hex(random_bytes(16));}
function auth(array $m,string $name,string $password):StaffSessionIdentity{global$db;$q=$db->prepare('SELECT outlet_code FROM outlets WHERE outlet_id=?');$q->execute([$m['loginOutlet']]);$n=(new StaffAccountService($db,$q->fetchColumn(),getenv('KIOS_MERCHANT_AUTH_RATE_KEY')))->authenticate($name,$password,'m05e-synthetic');ok($n!==null);$s=[];StaffAccountService::bind($s,$n);$s['_merchant_login_outlet']=$m['loginOutlet'];return new StaffSessionIdentity($db,static fn()=>$s,getenv('KIOS_MERCHANT_AUTH_RATE_KEY'));}
$service=new BillDrafts($db,auth($a,$a['username'],$secrets['owner_a_password']));
if(($argv[4]??'')==='worker'){try{echo json_encode($service->save($a['merchant'],$a['outlet'],$argv[5],$argv[6],$argv[7],$argv[8],'equal','3','1','Synthetic bounded discount',[]));exit;}catch(Throwable $e){echo json_encode(['error'=>get_class($e),'message'=>$e->getMessage(),'file'=>basename($e->getFile()),'line'=>$e->getLine()]);exit(1);}}
$load=fn($id='')=>$service->load($a['merchant'],$a['outlet'],$id);$all=$load();$id=$all['services'][0]['service_id'];$d=$load($id);$hash=$d['source']['hash'];$source=$d['source']['data'];
$save=fn($request,$version,$mode='equal',$people='3',$off='1',$reason='Synthetic bounded discount',$alloc=[])=>$service->save($a['merchant'],$a['outlet'],$request,$id,$version,$hash,$mode,$people,$off,$reason,$alloc);
function fp():array{global$db;$out=[];foreach(['orders','order_items','payment_confirmations','print_jobs','merchant_inventory_items','merchant_inventory_events','merchant_inventory_movements','merchant_service_sessions','merchant_seating_tables']as$t){$rows=$db->query('SELECT * FROM '.$t.' ORDER BY 1')->fetchAll(PDO::FETCH_ASSOC);$out[$t]=hash('sha256',serialize($rows));}return$out;}$before=fp();
test('Authoritative source and deterministic equal remainder reconcile',function()use($save,$load,$id,$source){$save(req(),'0');$x=json_decode($load($id)['draft']['snapshot_json'],true);ok($x['total']===$source['subtotal']-1);ok(array_sum($x['portions'])===$x['total']);ok(max($x['portions'])-min($x['portions'])<=1);});
test('Idempotency stale versions and conflicting request identifiers',function()use($save,$load,$id){$key=req();$v=(string)$load($id)['draft']['version'];$r=$save($key,$v);ok($save($key,$v)===$r);deny(fn()=>$save(req(),$v));deny(fn()=>$save($key,$v,'equal','2'));});
test('Items require complete exact quantity allocation and reconcile discounted portions',function()use($source,$save,$load,$id){$alloc=[];foreach($source['items']as$i)$alloc[(string)$i['order_item_id']]=[(string)((int)$i['quantity']-1),'1'];$v=(string)$load($id)['draft']['version'];$save(req(),$v,'items','2','1','Approved synthetic discount',$alloc);$x=json_decode($load($id)['draft']['snapshot_json'],true);ok(array_sum($x['portions'])===$source['subtotal']-1);foreach([[],array_map(fn($q)=>['0','0'],$alloc),array_map(fn($q)=>['-1','1'],$alloc),array_map(fn($q)=>['99','99'],$alloc)]as$bad)deny(fn()=>$save(req(),(string)$load($id)['draft']['version'],'items','2','1','Synthetic',$bad));});
test('Negative oversized discounts floats injection and missing reasons are rejected',function()use($save,$load,$id,$source){foreach(['-1','0.1','100000001',"1 OR 1=1"]as$x)deny(fn()=>$save(req(),(string)$load($id)['draft']['version'],'equal','2',$x));deny(fn()=>$save(req(),(string)$load($id)['draft']['version'],'equal','2','1',''));deny(fn()=>$save(req(),(string)$load($id)['draft']['version'],'equal','0'));});
test('Merchant outlet staff role and unauthorized discount isolation',function()use($service,$a,$b,$db,$load,$id,$hash,$secrets){deny(fn()=>$service->load($b['merchant'],$b['outlet']));deny(fn()=>$service->load($a['merchant'],$b['outlet']));$staff=json_decode(file_get_contents('C:/Mapped/Results/m05b-staff.json'),true);$cash=new BillDrafts($db,auth($a,$staff['cashier']['username'],$staff['cashier']['password']));deny(fn()=>$cash->save($a['merchant'],$a['outlet'],req(),$id,(string)$load($id)['draft']['version'],$hash,'equal','2','2','Unauthorized',[]));$k=new BillDrafts($db,auth($a,$staff['kitchen']['username'],$staff['kitchen']['password']));deny(fn()=>$k->load($a['merchant'],$a['outlet']));$other=new BillDrafts($db,auth($b,$b['username'],$secrets['owner_b_password']));deny(fn()=>$other->load($a['merchant'],$a['outlet'],$id));});
test('Source revision drift is visibly stale and old hash cannot save',function()use($db,$source,$load,$id,$save){$order=(int)$source['order']['order_id'];$db->exec("UPDATE merchant_service_sessions SET version=version+1 WHERE order_id=$order");try{ok($load($id)['stale']);deny(fn()=>$save(req(),(string)$load($id)['draft']['version']));}finally{$db->exec("UPDATE merchant_service_sessions SET version=version-1 WHERE order_id=$order");}});
test('Audit write failure rolls back draft revision atomically',function()use($db,$save,$load,$id){$v=$load($id)['draft'];$db->exec("CREATE TRIGGER bill_test_failure BEFORE INSERT ON merchant_bill_revisions FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic audit outage'");try{deny(fn()=>$save(req(),(string)$v['version']));ok($load($id)['draft']===$v);}finally{$db->exec('DROP TRIGGER bill_test_failure');}});
test('Actual concurrent identical requests produce one immutable revision',function()use($argv,$id,$hash,$save,$load,&$r){$key=req();$v=(string)$load($id)['draft']['version'];$workers=[];for($i=0;$i<2;$i++){$pipes=[];$p=proc_open([PHP_BINARY,__FILE__,$argv[1],$argv[2],$argv[3],'worker',$key,$id,$v,$hash],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);ok(is_resource($p));fclose($pipes[0]);$workers[]=[$p,$pipes];}$out=[];foreach($workers as[$p,$pipes]){$stdout=stream_get_contents($pipes[1]);$stderr=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($p);$r['workers'][]=['exit'=>$exit,'stderr'=>$stderr,'response'=>$stdout];ok($exit===0);$out[]=json_decode($stdout,true);}ok($out[0]===$out[1]);ok((int)$load($id)['draft']['version']===(int)$v+1);});
test('History cannot be updated or deleted and cancellation is terminal',function()use($db,$service,$a,$id,$hash,$load){deny(fn()=>$db->exec('DELETE FROM merchant_bill_revisions'));deny(fn()=>$db->exec("UPDATE merchant_bill_revisions SET operation='fake'"));$v=(string)$load($id)['draft']['version'];$service->save($a['merchant'],$a['outlet'],req(),$id,$v,$hash,'equal','2','1','Synthetic cancel',[],true);ok($load($id)['draft']['status']==='CANCELLED');deny(fn()=>$service->save($a['merchant'],$a['outlet'],req(),$id,(string)((int)$v+1),$hash,'equal','2','1','Synthetic',[]));});
test('No order price payment inventory table or print mutation; UTC audit attribution',function()use($before,$db){ok(fp()===$before);ok((int)$db->query('SELECT COUNT(*) FROM payment_confirmations')->fetchColumn()===0);ok((int)$db->query("SELECT COUNT(*) FROM merchant_bill_revisions WHERE occurred_epoch<UNIX_TIMESTAMP()-300 OR actor_id IS NULL")->fetchColumn()===0);});
file_put_contents($argv[3],json_encode($r,JSON_PRETTY_PRINT));echo json_encode($r);exit($r['failed']?1:0);
